package ama.config.json;
import ama.contract.MinutesContracts.*;
import ama.contract.TaskContracts.TaskSpec;
import ama.minutes.contract.*;
import ama.transcript.TranscriptAcquisitionBudget;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static ama.config.json.ConfigBindingsTest.*;
import static ama.config.json.RawHashChainTest.*;
class Task09CandidatePlanTest {
 record Fixture(TaskSpec spec,ValidatedOutput output,Catalog catalog,List<FullRow> rows){}
 Fixture fixture(){var facts=storedGeneration();var spec=facts.taskSpecs().getLast();var binding=service().verifyGeneration(new GenerationFacts(G,facts),spec,full(),GRAPH,B,()->false);var catalog=binding.catalog();String alias=catalog.sources().getFirst().sourceId();var sources=new SourceIds(List.of(alias));var elements=new EnumMap<Category,List<Element>>(Category.class);var evidence=new ArrayList<Evidence>();evidence.add(new Evidence(new BodyTarget(0,2),sources));for(var category:Category.values()){String key=category.name();elements.put(category,List.of(new Element(key,category.name(),category==Category.ACTION?new Action("Unaccepted owner","2026-11-01"):null)));evidence.add(new Evidence(new ElementTarget(key,0,1),sources));}var output=new Output("ama.minutes-output.v1",spec.inputFingerprint(),"Original AI title","😀 body",elements,List.of(new Detection("d1",SensitiveKind.INTERNAL_BUSINESS_DATA,sources),new Detection("d2",SensitiveKind.POLITICAL_SENSITIVE,sources)),List.of(new Note("n1","Original background",sources)),List.of(new Ref(alias,catalog.sources().getFirst().fact().locator())),evidence);return new Fixture(spec,new OutputValidation().validate(output,new ValidationContext(spec.inputFingerprint(),spec.inputFingerprint(),Scope.FULL,catalog),()->false),catalog,facts.rows());}
 Object plan(Fixture f)throws Exception {Class<?> type=assertDoesNotThrow(()->Class.forName("ama.transcript.MinutesCandidateGraphPlan"));var ledger=new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,8388608,128,256,256).ledger(B,GRAPH.canonical(),()->false);return type.getMethod("prepare",TaskSpec.class,String.class,String.class,ValidatedOutput.class,Catalog.class,List.class,TranscriptAcquisitionBudget.Ledger.class).invoke(null,f.spec(),"original-owner",null,f.output(),f.catalog(),f.rows(),ledger);}
 @SuppressWarnings("unchecked") List<FullRow> rows(Object plan,long body,long set)throws Exception{return (List<FullRow>)plan.getClass().getMethod("rows",long.class,long.class).invoke(plan,body,set);}
 @Test void completeCandidatePlanRemapsEveryTableAndGrantsNoAcceptedActionOrReview()throws Exception {
  var f=fixture();var rows=rows(plan(f),7,9);assertEquals(7,rows.stream().filter(r->r.table()==Table.MINUTES_ELEMENT).count());var body=rows.stream().filter(r->r.table()==Table.MINUTES_REVISION).findFirst().orElseThrow();assertEquals(7,body.number("revision"));assertEquals("AI",body.string("title_origin"));assertEquals("Original AI title",body.string("title"));assertEquals(f.spec().input().id(),body.string("generation_input_id"));assertEquals(9,rows.stream().filter(r->r.table()==Table.ELEMENT_SET).findFirst().orElseThrow().number("revision"));assertEquals(8,rows.stream().filter(r->r.table()==Table.EVIDENCE_LINK).count());assertTrue(rows.stream().filter(r->r.table()==Table.EVIDENCE_LINK).allMatch(r->r.string("support_state").equals("PARTIAL")&&(r.nullableString("element_id")==null)!=(r.nullableString("minutes_revision_id")==null)));assertTrue(rows.stream().filter(r->r.table()==Table.ACTION_ITEM).allMatch(r->r.nullableString("owner_enterprise_id")==null&&r.nullableString("owner_display")==null&&r.nullableString("due_on")==null));var suggestion=rows.stream().filter(r->r.table()==Table.ACTION_SUGGESTION).findFirst().orElseThrow();assertEquals("Unaccepted owner",suggestion.string("owner_mention"));assertEquals("2026-11-01",suggestion.string("due_on"));assertEquals(2,rows.stream().filter(r->r.table()==Table.SENSITIVE_DETECTION_SOURCE).count());assertEquals(1,rows.stream().filter(r->r.table()==Table.BACKGROUND_NOTE_SOURCE).count());assertTrue(rows.stream().noneMatch(r->r.table()==Table.RESULT_REVIEW));assertEquals(1,rows.stream().filter(r->r.table()==Table.EVIDENCE_LINK).map(r->r.string("locator_id")).distinct().count());
 }
 @Test void independentPlansUseDifferentServerIdsAndOnlyHistorySlotsAreBoundLater()throws Exception {var f=fixture();var plan=plan(f);var a=rows(plan,3,8);var b=rows(plan,4,11);assertEquals(a.stream().map(r->r.table()+":"+r.cells().getFirst()).toList(),b.stream().map(r->r.table()+":"+r.cells().getFirst()).toList());for(int n=0;n<a.size();n++)if(a.get(n).table()!=Table.MINUTES_REVISION&&a.get(n).table()!=Table.ELEMENT_SET)assertEquals(a.get(n),b.get(n));assertNotEquals(a.stream().filter(r->r.table()==Table.MINUTES_REVISION).findFirst().orElseThrow().string("id"),rows(plan(f),3,8).stream().filter(r->r.table()==Table.MINUTES_REVISION).findFirst().orElseThrow().string("id"));}
}
